	public static abstract class AbstractTestStubAnalyzer : Analyzer {

		protected AnalysisOptionsUpdater updater = new AnalysisOptionsUpdater();

		private static readonly string NAME = "Test Analyzer";

		/* @Override */
		public string getName() {
			return NAME;
		}

		/* @Override */
		public AnalyzerType getAnalysisType() {
			return AnalyzerType.FUNCTION_ANALYZER;
		}

		/* @Override */
		public bool getDefaultEnablement(Program p) {
			return true;
		}

		/* @Override */
		public bool supportsOneTimeAnalysis() {
			return false;
		}

		/* @Override */
		public string getDescription() {
			return "Test analyzer...";
		}

		/* @Override */
		public AnalysisPriority getPriority() {
			return AnalysisPriority.FUNCTION_ANALYSIS;
		}

		/* @Override */
		public bool canAnalyze(Program p) {
			return true;
		}

		/* @Override */
		public bool added(Program p, AddressSetView set, TaskMonitor monitor,
				MessageLog log)
    {
			return false;
		}

		/* @Override */
		public bool removed(Program p, AddressSetView set, TaskMonitor monitor,
				MessageLog log)
    {
			return false;
		}

		/* @Override */
		public void registerOptions(Options options, Program p) {

			options.registerOption(UNCHANGING_OPTION_NAME, UNCHANGING_OPTION_DEFAULT_VALUE, null,
				"Unchanging option description");

			// replaces "Old Name"
			options.registerOption(NEW_OPTION_NAME, NEW_OPTION_DEFAULT_VALUE, null,
				"New option description");
		}

		/* @Override */
		public AnalysisOptionsUpdater getOptionsUpdater() {
			return updater;
		}

		/* @Override */
		public void optionsChanged(Options options, Program p) {
			// stub
		}

		/* @Override */
		public void analysisEnded(Program p) {
			// stub
		}

		/* @Override */
		public bool isPrototype() {
			return false;
		}
	}

	public static class NotReplacingTestStubAnalyzer : AbstractTestStubAnalyzer {

		public NotReplacingTestStubAnalyzer() : base()
    {

			updater.registerReplacement(NEW_OPTION_NAME, OLD_OPTION_NAME, oldValue => {
				throw new AssertException(
					"Replace function unexpectedly called for new/old options: '" +
						NEW_OPTION_NAME + "' / '" + OLD_OPTION_NAME + "'");
			});
		}
	}

	public static class UseOldValueTestStubAnalyzer : AbstractTestStubAnalyzer {

		public UseOldValueTestStubAnalyzer() : base()
    {

			updater.registerReplacement(NEW_OPTION_NAME, OLD_OPTION_NAME, oldValue => {
				return oldValue;
			});
		}
	}

	public static class ConvertValueTypeTestStubAnalyzer : AbstractTestStubAnalyzer {

		public ConvertValueTypeTestStubAnalyzer() : base()
    {

			updater.registerReplacement(NEW_OPTION_NAME, OLD_OPTION_NAME, oldValue => {
				// Assumption: 'oldValue' is an RGB string; the new value expects a Color
				return toColor((string) oldValue);
			});
		}

		/* @Override */
		public void registerOptions(Options options, Program p) {

			options.registerOption(UNCHANGING_OPTION_NAME, UNCHANGING_OPTION_DEFAULT_VALUE, null,
				"Unchanging option description");

			// replaces "Old Name"
			options.registerOption(NEW_OPTION_NAME, NEW_OPTION_DEFAULT_VALUE_AS_COLOR, null,
				"New option description");

		}
	}
